package pca

// Differential kill test for decideIntentWB (the W-B unit, rules 16-18, intent_wb.go) against the TypeScript reference
// decideIntentWB: testdata/k042-wbmisc.json.gz is generated by tools/pca-audit/java-mutate/k042-wbmisc-oracle.mjs (shared with
// the Java suite). Every case compares the outcome and the checks (name -> pass / question / fail); the reason text is compared exactly. Cases whose input cannot be expressed through Go's typed signature (a missing / non-string aud or session,
// a non-numeric now, a non-object action or intent_session) are skipped: Go's callers (decideIntentV2) never reach them.

import (
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"strings"
	"testing"
)

func TestK042WbMiscCorpus(t *testing.T) {
	f, err := os.Open("testdata/k042-wbmisc.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
	b, err := io.ReadAll(zr)
	if err != nil {
		t.Fatal(err)
	}
	doc, err := ParseJSONLenient(b)
	if err != nil {
		t.Fatal(err)
	}
	cases := doc.(map[string]any)["cases"].([]any)
	var bad []string
	ran, skipped := 0, 0
	var td textDiffs
	for _, co := range cases {
		c := co.(map[string]any)
		name := c["name"].(string)
		in := normalizeJSON(c["input"]).(map[string]any)
		exp := normalizeJSON(c["expect"]).(map[string]any)
		now, nowOK := jsNum(in["now"])
		aud, audOK := in["aud"].(string)
		session, sessOK := in["session"].(string)
		action, actOK := in["action"].(map[string]any)
		is, isOK := in["intent_session"].(map[string]any)
		if a, has := in["artifacts"]; has && a == nil {
			// wb.artifacts: null never reaches decideIntentWB: the v2 context validator (wbCtxError) refuses it first, and the
			// accessor cannot tell a present null from an absent member
			skipped++
			continue
		}
		if !nowOK || !audOK || !sessOK || !actOK || !isOK {
			skipped++
			continue
		}
		ran++
		var r wbResult
		func() {
			defer func() {
				if x := recover(); x != nil {
					bad = append(bad, fmt.Sprintf("%s: threw %v", name, x))
				}
			}()
			var artifacts any
			if a, has := in["artifacts"]; has {
				artifacts = a
			}
			policy, hasPol := in["policy"]
			if !hasPol {
				policy = map[string]any{} // as decideIntentV2 passes an absent wb.policy
			}
			r = decideIntentWB(now, aud, session, action, is, artifacts, policy)
		}()
		if r.outcome == "" {
			continue
		}
		if r.outcome != exp["outcome"] {
			bad = append(bad, fmt.Sprintf("%s: outcome want %v got %v (%s)", name, exp["outcome"], r.outcome, r.reason))
			continue
		}
		want := map[string]any{}
		for _, ck := range exp["checks"].([]any) {
			kv := ck.([]any)
			want[kv[0].(string)] = kv[1]
		}
		wc, _ := canonicalLenient(want)
		gm := map[string]any{}
		for k, v := range r.checks {
			gm[k] = v
		}
		gc, _ := canonicalLenient(gm)
		if wc != gc {
			bad = append(bad, fmt.Sprintf("%s: checks want %s got %s", name, wc, gc))
			continue
		}
		if r.reason != fmt.Sprint(exp["reason"]) && !(exp["reason"] == nil && r.reason == "") {
			td.add(fmt.Sprint(exp["reason"]), r.reason)
		}
	}
	t.Logf("%d cases run, %d skipped (not expressible)", ran, skipped)
	td.finish(t)
	if ran < 500 {
		t.Fatalf("only %d cases ran", ran)
	}
	if len(bad) > 0 {
		if len(bad) > 40 {
			bad = bad[:40]
		}
		t.Fatalf("%d mismatches:\n%s", len(bad), strings.Join(bad, "\n"))
	}
}
